def sat(z, k, kind):
    if kind == 't':
        return np.tanh(k * z)
    if kind == 'r':
        return z / (1 + (k * z) ** 2)
    if kind == 's':
        return z / np.sqrt(1 + (k * z) ** 2)
    if kind == 'a':
        return np.arctan(k * z)
    if kind == 'e':
        return z * np.exp(-(k * z) ** 2)

def design(x, p, spec):
    (ku, kv, nu, nv, cross) = spec
    (u, v) = x.T
    cols = [np.ones(len(u))] + [u ** i for i in range(1, nu + 1)] + [v ** i for i in range(1, nv + 1)]
    if ku:
        cols.append(sat(u, p[0], ku))
    if kv:
        cols.append(sat(v, p[1], kv))
    if cross:
        cols += [u * v, u * u * v, u * v * v]
    return np.column_stack(cols)

def fit(x, y, spec):
    from scipy.optimize import least_squares

    def coef(p):
        D = design(x, p, spec)
        return np.linalg.lstsq(D, y, rcond=1e-10)[0]

    def err(p):
        return design(x, p, spec) @ coef(p) - y
    p = least_squares(err, [1.1, 0.8], bounds=(0.1, 4), max_nfev=70).x
    return (p, coef(p))
